from pathlib import Path
import argparse,json,hashlib,time,importlib.metadata as md
import numpy as np
from PIL import Image,ImageDraw
import torch
from transformers import AutoImageProcessor,AutoModelForDepthEstimation
ap=argparse.ArgumentParser();ap.add_argument('--metadata',required=True);a=ap.parse_args();p=Path(__file__).resolve().parent;m=json.loads(Path(a.metadata).read_text());s=Path(m['path']);o=p/m['output_name'];o.mkdir(exist_ok=True);sha=lambda f:hashlib.sha256(f.read_bytes()).hexdigest();assert sha(s)==m['sha256'];im=Image.open(s).convert('RGB');art=json.loads((p/'provenance/model-manifest.json').read_text())
for f in art['artifacts']:assert sha(p/'model'/f['path'])==f['sha256']
torch.set_num_threads(1);torch.set_num_interop_threads(1);proc=AutoImageProcessor.from_pretrained(p/'model',local_files_only=True,trust_remote_code=False,use_fast=False);model=AutoModelForDepthEstimation.from_pretrained(p/'model',local_files_only=True,trust_remote_code=False,use_safetensors=True).eval();x=proc(images=im,return_tensors='pt');start=time.time()
with torch.inference_mode():raw=model(**x).predicted_depth[0].cpu().numpy().astype('float32')
sec=time.time()-start;finite=np.isfinite(raw);lo=float(raw[finite].min());hi=float(raw[finite].max());assert hi>lo;np.save(o/'relative-inverse-depth-model-grid.npy',raw,allow_pickle=False);Image.fromarray((np.clip((raw-lo)/(hi-lo),0,1)*65535).round().astype('uint16')).save(o/'relative-inverse-depth-gray16-model-grid.png');res=torch.nn.functional.interpolate(torch.from_numpy(raw)[None,None],size=(im.height,im.width),mode='bicubic',align_corners=False)[0,0].numpy();np.save(o/'relative-inverse-depth-resampled-screenshot-grid.npy',res,allow_pickle=False);Image.fromarray((np.clip((res-lo)/(hi-lo),0,1)*255).round().astype('uint8')).save(o/'relative-inverse-depth-gray8-resampled-screenshot-grid.png');mask=Image.new('L',im.size);d=ImageDraw.Draw(mask)
for r in m['exclusions']:d.polygon([tuple(pt) for pt in r['points']],fill=r['class'])
mask.save(o/'manual-exclusion-classes-screenshot-grid.png');Image.new('L',im.size,255).save(o/'confidence-unknown-screenshot-grid.png');Image.fromarray((~finite).astype('uint8')*255).save(o/'nonfinite-invalid-model-grid.png');dark=np.asarray(im).max(axis=2)<=25;Image.fromarray(dark.astype('uint8')*255).save(o/'dark-low-signal-caution-screenshot-grid.png')
r={'source':{**m,'dimensions':list(im.size),'bytes':s.stat().st_size,'crop':[0,0,im.width,im.height]},'method':{**art,'versions':{k:md.version(k) for k in ['torch','transformers','numpy','pillow','safetensors']},'input_tensor_shape':list(x['pixel_values'].shape),'raw_shape':list(raw.shape),'processor_config':json.loads((p/'model/preprocessor_config.json').read_text()),'dtype':'float32','device':'cpu','threads':1,'trust_remote_code':False,'local_files_only':True,'forward_seconds':sec},'range':{'min':lo,'max':hi,'nonfinite_count':int((~finite).sum())},'definition':'Relative inverse-depth-like prediction; larger/white generally nearer, smaller/black farther; NOT image luminance, metric distance or geometry acceptance. Per-image normalization not cross-view scale.','resampling':'Bicubic align_corners=False from model grid to screenshot grid, NOT independent full-resolution depth; no source interpolation claimed.','masks':{'manual':'Conservative incomplete ROIs, later drawn overwrite;0 unlabelled NOT certified valid.','confidence_unknown':'255 everywhere means NO calibrated confidence, NOT high confidence.','nonfinite':'255 numerical nonfinite;0 only finite, not valid geometry.','dark':'All original RGB<=25 heuristic caution, NOT depth algorithm.','occlusion':'Hidden geometry unknown; do not fill as fact.'},'limitations':['Article screenshot is NOT logged-in highest-quality decoded native video frame','Video timestamp/decoder/native dimensions unverified','Stylized CGI, compositing, reflection, transparency, light, shadows and characters may break predictions','No camera, distance, dimensions, contact, hidden surfaces, subsequent replay or geometry acceptance established']}
r['outputs']=[{'path':f.name,'bytes':f.stat().st_size,'sha256':sha(f)} for f in sorted(o.iterdir()) if f.is_file() and f.name!='report.json'];(o/'report.json').write_text(json.dumps(r,ensure_ascii=False,indent=2));print(o,r['range'],sec,flush=True)
